package dev.hrutvik.billing.invoice;
import com.fasterxml.jackson.databind.ObjectMapper; import dev.hrutvik.billing.outbox.*; import dev.hrutvik.billing.rating.*; import org.junit.jupiter.api.Test; import java.math.BigDecimal; import java.time.*; import java.util.*; import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.Mockito.*;
class InvoiceServiceTest {
 private final InvoiceStore store=mock(InvoiceStore.class); private final RatingService rating=mock(RatingService.class); private final OutboxEventRepository outbox=mock(OutboxEventRepository.class); private final Instant now=Instant.parse("2026-11-05T12:00:00Z"); private final InvoiceService service=new InvoiceService(store,rating,outbox,new ObjectMapper(),Clock.fixed(now,ZoneOffset.UTC)); private final UUID subscription=UUID.randomUUID(); private final Instant from=Instant.parse("2026-11-01T00:00:00Z"); private final Instant to=Instant.parse("2026-12-01T00:00:00Z");
 @Test void finalizesInvoiceLinesPricingSnapshotAndOutboxAtomically(){when(store.lockSubscription("tenant-a",subscription)).thenReturn(new SubscriptionPlan(subscription,UUID.randomUUID(),"USD"));when(store.existing("tenant-a",subscription,from,to)).thenReturn(Optional.empty());var tier=new PriceTier(BigDecimal.ZERO,null,new BigDecimal("0.01"));when(rating.preview("tenant-a",subscription,from,to)).thenReturn(new RatingPreview(subscription,"USD",from,to,List.of(new RatingLine("api_calls",new BigDecimal("1250"),new BigDecimal("12.50"),List.of(tier))),new BigDecimal("12.50")));var result=service.finalizePeriod("tenant-a",subscription,from,to);assertThat(result.status()).isEqualTo("FINALIZED");assertThat(result.replayed()).isFalse();verify(store).insertInvoice(any(),startsWith("INV-"),eq("tenant-a"),eq(subscription),eq("USD"),eq(from),eq(to),eq(new BigDecimal("12.50")),eq(now));verify(store).insertLine(any(),eq(result.invoiceId()),eq("api_calls"),eq(new BigDecimal("1250")),eq(new BigDecimal("12.50")),contains("unitPrice"));verify(outbox).save(any(OutboxEvent.class));}
 @Test void exactPeriodReplayReturnsExistingInvoiceWithoutRerating(){var existing=new InvoiceResponse(UUID.randomUUID(),"INV-EXIST",subscription,"USD",from,to,new BigDecimal("12.50"),"FINALIZED",List.of(),true);when(store.existing("tenant-a",subscription,from,to)).thenReturn(Optional.of(existing));assertThat(service.finalizePeriod("tenant-a",subscription,from,to)).isSameAs(existing);verifyNoInteractions(rating,outbox);verify(store,never()).insertInvoice(any(),any(),any(),any(),any(),any(),any(),any(),any());}
}
